<section class="opsSection" id="activity-log"><div class="appSectionHeading"><div><span class="sectionKicker">RECENT CHANGES</span><h2>Activity log</h2><p>See the latest customer, quote, project, and account updates.</p></div><span class="sectionCounter"><?= count($activity) ?> RECENT EVENTS</span></div><?php if (!$activity): ?><div class="emptyState compactEmpty"><strong>No activity has been recorded yet.</strong><p>Changes made in this dashboard will appear here.</p></div><?php else: ?><div class="activityList"><?php foreach ($activity as $event): ?><article class="activityItem"><span class="activityDot"></span><div><strong><?= esc($event['description']) ?></strong><p><?= esc(ucfirst($event['entity_type'])) ?><?= $event['entity_id'] ? ' #' . esc($event['entity_id']) : '' ?> · <?= esc(trim(($event['first_name'] ?? 'System') . ' ' . ($event['last_name'] ?? ''))) ?></p></div><time datetime="<?= esc(date(DATE_ATOM, strtotime($event['created_at']))) ?>"><?= esc(date('M j, Y · g:i A', strtotime($event['created_at']))) ?></time></article><?php endforeach ?></div><?php endif ?></section>
